function difficultyForIndex(index: number): Difficulty {
  if (index % 5 === 4) {
    return "hard";
  }

  if (index % 4 === 0 || index % 20 === 1) {
    return "easy";
  }

  return "medium";
}

function rotateOptions(options: string[], index: number): { options: string[]; correctAnswer: number } {
  const shift = index % options.length;
  const rotated = [...options.slice(shift), ...options.slice(0, shift)];
  return { options: rotated, correctAnswer: rotated.indexOf(options[0]) };
}

function normalize(value: string): string {
  return value
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function tokenSimilarity(left: string, right: string): number {
  const leftTokens = new Set(left.split(" ").filter(Boolean));
  const rightTokens = new Set(right.split(" ").filter(Boolean));

  if (!leftTokens.size || !rightTokens.size) {
    return 0;
  }

  const intersection = [...leftTokens].filter((token) => rightTokens.has(token)).length;
  const union = new Set([...leftTokens, ...rightTokens]).size;
  return intersection / union;
}

async function readQuestionsIfExists(relativeFilePath: string): Promise<Question[]> {
  try {
    return JSON.parse(await fs.readFile(path.join(projectRoot, relativeFilePath), "utf8")) as Question[];
  } catch {
    return [];
  }
}

async function loadComparisonQuestions(outputFiles: string[]): Promise<Question[]> {
  const files = [
    "public/data/questions/tznk.json",
    "public/data/questions/english.json",
    "public/data/questions/management.json",
    "public/data/questions/psychology-sociology.json",
    "data/generated/tznk.generated.json",
    "data/generated/english.generated.json",
    "data/processed/third-party/tznk.third-party.json",
    "data/processed/third-party/english.third-party.json",
    "data/processed/third-party/management.third-party.json",
    "data/processed/third-party/psychology-sociology.third-party.json"
  ].filter((file) => !outputFiles.includes(file));

  const questions = await Promise.all(files.map(readQuestionsIfExists));
  return questions.flat();
}

function buildQuestions(batch: SubjectBatch): Question[] {
  if (batch.seeds.length !== 100) {
    throw new Error(`${batch.subject} must have exactly 100 seeds, found ${batch.seeds.length}.`);
  }

  return batch.seeds.map((item, index) => {
    const { options, correctAnswer } = rotateOptions([item.correct, ...item.distractors], index);

    return {
      id: `${batch.idPrefix}-${String(index + 1).padStart(3, "0")}`,
      subject: batch.subject,
      type: "single_choice",
      topic: item.topic,
      subtopic: item.subtopic,
      difficulty: difficultyForIndex(index),
      sourceType: "generated",
      sourceUrl: null,
      reviewed: false,
      question: item.question,
      options,
      correctAnswer,
      explanation: item.explanation,
      tags: ["generated_batch_2", batch.subjectTag]
    };
  });
}

function assertNoDuplicates(newQuestions: Question[], comparisonQuestions: Question[]): void {
  const seenIds = new Map<string, string>();
  const seenTexts = new Map<string, string>();

  for (const question of comparisonQuestions) {
    seenIds.set(question.id, question.id);
    seenTexts.set(`${question.subject}:${normalize(question.question)}`, question.id);
  }

  const previousBySubject = new Map<string, Question[]>();
  for (const question of comparisonQuestions) {
    previousBySubject.set(question.subject, [...(previousBySubject.get(question.subject) ?? []), question]);
  }

  for (const question of newQuestions) {
    if (seenIds.has(question.id)) {
      throw new Error(`Duplicate id detected before writing: ${question.id}`);
    }

    const normalizedQuestion = normalize(question.question);
    const textKey = `${question.subject}:${normalizedQuestion}`;
    const duplicateTextId = seenTexts.get(textKey);

    if (duplicateTextId) {
      throw new Error(`Duplicate question text detected before writing: ${question.id} duplicates ${duplicateTextId}`);
    }

    for (const previous of previousBySubject.get(question.subject) ?? []) {
      const previousText = normalize(previous.question);
      const shorter = Math.min(previousText.length, normalizedQuestion.length);
      const longer = Math.max(previousText.length, normalizedQuestion.length);

      if (shorter >= 80 && shorter / longer >= 0.9 && tokenSimilarity(previousText, normalizedQuestion) >= 0.94) {
        throw new Error(`Near-duplicate question detected before writing: ${question.id} is close to ${previous.id}`);
      }
    }

    seenIds.set(question.id, question.id);
    seenTexts.set(textKey, question.id);
    previousBySubject.set(question.subject, [...(previousBySubject.get(question.subject) ?? []), question]);
  }
}

function countBy<T extends string>(questions: Question[], getter: (question: Question) => T): Record<T, number> {
  return questions.reduce<Record<T, number>>((accumulator, question) => {
    const key = getter(question);
    accumulator[key] = (accumulator[key] ?? 0) + 1;
    return accumulator;
  }, {} as Record<T, number>);
}

function linesFromCounts(counts: Record<string, number>): string {
  return Object.entries(counts)
    .sort(([left], [right]) => left.localeCompare(right, "uk"))
    .map(([label, count]) => `- ${label}: ${count}`)
    .join("\n");
}

function buildReport(managementQuestions: Question[], psychologySociologyQuestions: Question[]): string {
  return `# Generated Batch 2 Report

Generated on 2026-05-19.

## Counts

- Управління та адміністрування: ${managementQuestions.length}
- Психологія та соціологія: ${psychologySociologyQuestions.length}
- Total: ${managementQuestions.length + psychologySociologyQuestions.length}

## Management Topic Distribution

${linesFromCounts(countBy(managementQuestions, (question) => question.topic))}

## Psychology And Sociology Topic Distribution

${linesFromCounts(countBy(psychologySociologyQuestions, (question) => question.topic))}

## Difficulty Distribution

Management:
${linesFromCounts(countBy(managementQuestions, (question) => question.difficulty))}

Psychology and sociology:
${linesFromCounts(countBy(psychologySociologyQuestions, (question) => question.difficulty))}

## Known Limitations

- Questions are original generated training items, not official exam tasks.
- All items are marked \`reviewed=false\` and should receive human quality review before merge.
- Some applied scenarios intentionally simplify real organizational or social situations for single-choice practice.

## Recommendation

Review batch 2 with the same strict process used for generated batch 1. Merge only items that pass answer, ambiguity, terminology, and duplicate checks.

## Verification

- Validation: pending \`npm run validate:questions\`
- Build: pending \`npm run build\`
`;
}

async function main(): Promise<void> {
  const batches: SubjectBatch[] = [
    {
      subject: "management",
      idPrefix: "management-generated-b2",
      outputFile: "data/generated/management.generated-batch-2.json",
      subjectTag: "generated_management",
      seeds: managementSeeds
    },
    {
      subject: "psychology-sociology",
      idPrefix: "psych-soc-generated-b2",
      outputFile: "data/generated/psychology-sociology.generated-batch-2.json",
      subjectTag: "generated_psychology_sociology",
      seeds: psychologySociologySeeds
    }
  ];

  const outputFiles = batches.map((batch) => batch.outputFile);
  const comparisonQuestions = await loadComparisonQuestions(outputFiles);
  const managementQuestions = buildQuestions(batches[0]);
  const psychologySociologyQuestions = buildQuestions(batches[1]);
  const generatedQuestions = [...managementQuestions, ...psychologySociologyQuestions];

  assertNoDuplicates(generatedQuestions, comparisonQuestions);

  await fs.mkdir(path.join(projectRoot, "data", "generated"), { recursive: true });
  await fs.writeFile(
    path.join(projectRoot, batches[0].outputFile),
    `${JSON.stringify(managementQuestions, null, 2)}\n`,
    "utf8"
  );
  await fs.writeFile(
    path.join(projectRoot, batches[1].outputFile),
    `${JSON.stringify(psychologySociologyQuestions, null, 2)}\n`,
    "utf8"
  );
  await fs.writeFile(
    path.join(projectRoot, "data", "generated", "generated-batch-2-report.md"),
    buildReport(managementQuestions, psychologySociologyQuestions),
    "utf8"
  );

  console.log(`Generated ${managementQuestions.length} management questions.`);
  console.log(`Generated ${psychologySociologyQuestions.length} psychology-sociology questions.`);
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
});
